// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }

    // fuzzed params: an address that will be used as the `from` arg and a uint v
    // We also fuzz the length-1 recipient to keep things simple: one recipient so behavior is singular
    function testFuzz_property(address from, uint256 v) public {
        // keep `from` non-zero to be a realistic caller param; allow any v
        vm.assume(from != address(0));

        // Deploy a callee that will revert when called: this lets the fuzzer vary `from` and `v`
        Reverter rev = new Reverter();

        // Build a single-element tos array with the reverter contract as recipient
        address[] memory tos = new address[](1);
        tos[0] = address(rev);

        bool ok;
        // call transfer and catch revert; reference C should revert because it requires inner call success
        try c.transfer(from, address(rev), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (single assert): For any admissible inputs (non-empty tos, any from,v), the reference
        // implementation always reverts (ok == false) when the callee reverts. The mutant (which deletes the
        // require on the low-level call) will return true (ok == true) for the same input; thus this assertion
        // holds for the correct contract for all fuzz inputs and will fail on the buggy mutant for some input.
        assertTrue(!ok);
    }
}

// adversarial helper: always revert on the exact selector called by C
contract Reverter {
    // the target selector is transferFrom(address,address,uint256)
    // Provide a matching function that simply reverts
    function transferFrom(address, address, uint256) external pure {
        revert("forced revert");
    }
}
